// Simulate a post.failed trigger payload
return [{
  json: {
    event: 'post.failed',
    platform: 'x',
    postId: 'post_simulated_1',
    error: 'Rate limit exceeded',
    timestamp: new Date().toISOString(),
  },
}];

const input = $input.first().json;
const eventType = input.event || input.type || 'unknown';
const platform = input.platform || input.data?.platform || input.post?.platform || 'unknown';
const postId = input.postId || input.post?.id || input.data?.postId || null;
return [{
  json: {
    eventType,
    platform,
    postId,
    sourcePayload: input,
  },
}];

return [{
  json: {
    scenario: 'trigger_event_branch',
    branch: 'x_quota_sensitive',
    severity: 'high',
    action: 'route_to_quota_aware_alerting',
    eventType: $json.eventType,
    platform: $json.platform,
    postId: $json.postId,
    passed: true,
  },
}];

return [{
  json: {
    scenario: 'trigger_event_branch',
    branch: 'standard_platform',
    severity: 'medium',
    action: 'route_to_standard_failure_alerting',
